contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take arbitrary inputs: from, caddress, _tos array, and v.
    // The property: when _tos.length > 0, calling c.transfer must either revert,
    // or return true; and if it returns true then all internal calls must have succeeded.
    // We cannot observe the internal calls directly, but since transfer returns true only
    // after requiring each call's success, the observable rule is: if call does not revert,
    // it returns true. We express that: when _tos.length>0, the call does not both
    // succeed and return false; equivalently, if it returns (no revert) then returned value == true.
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        require(_tos.length > 0);
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // General rule: for any inputs with non-empty _tos, the call either reverts or returns true.
        // Therefore if it did not revert, the return value must be true.
        assert(reverted || ret == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // Single public test function taking inputs and asserting the general rule.
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        // No preconditions except those needed for the intended rule
        bool didRevert;
        bool returnedValue;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            didRevert = false;
            returnedValue = r;
        } catch {
            didRevert = true;
            returnedValue = false;
        }
        // Assert the general rule:
        // - if _tos is empty then the call must revert (require(_tos.length > 0) in C)
        // - otherwise, if it did not revert then it must have returned true
        assert((_tos.length == 0 && didRevert) || (_tos.length > 0 && (didRevert || returnedValue == true)));
    }
    receive() external payable {}
}

