contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking inputs and asserting the general rule.
    function run(address from, address caddress, address[] calldata _tos, uint v) public payable {
        // Require non-empty _tos to match C's require and simplify reasoning
        require(_tos.length > 0);

        // record balance of c before
        uint balBefore = address(c).balance;

        bool didRevert;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            didRevert = false;
            ret = r;
        } catch {
            didRevert = true;
            ret = false;
        }

        uint balAfter = address(c).balance;

        // Assert: either the call reverted, or it returned true and did not decrease c's balance
        assert(didRevert || (ret == true && balAfter >= balBefore));
    }

    receive() external payable {}
}
